fun oppositeEnds(a: IntArray, target: Int): IntArray {
    var left = 0
    var right = a.size - 1
    while (left < right) {
        val sum = a[left] + a[right]
        when {
            sum == target -> return intArrayOf(left, right)
            sum < target -> left++     // need a bigger sum
            else -> right--            // need a smaller sum
        }
    }
    return intArrayOf(-1, -1)
}
// Time: O(n)   Space: O(1)

fun sameDirection(a: IntArray): Int {
    var write = 0
    for (read in a.indices) {
        if (/* keep a[read] */ true) {
            a[write] = a[read]
            write++
        }
    }
    return write   // new length
}
// Time: O(n)   Space: O(1)

fun twoSequences(a: IntArray, b: IntArray) {
    var i = 0
    var j = 0
    while (i < a.size && j < b.size) {
        when {
            a[i] < b[j] -> i++
            a[i] > b[j] -> j++
            else -> { /* match found */ i++; j++ }
        }
    }
}
// Time: O(n + m)   Space: O(1)

fun twoSumSorted(numbers: IntArray, target: Int): IntArray {
    var l = 0
    var r = numbers.size - 1
    while (l < r) {
        val sum = numbers[l] + numbers[r]
        if (sum == target) return intArrayOf(l + 1, r + 1)  // 1-indexed
        if (sum < target) l++ else r--
    }
    return intArrayOf()
}
// Time: O(n)   Space: O(1)

fun isPalindrome(s: String): Boolean {
    var l = 0
    var r = s.length - 1
    while (l < r) {
        while (l < r && !s[l].isLetterOrDigit()) l++
        while (l < r && !s[r].isLetterOrDigit()) r--
        if (s[l].lowercaseChar() != s[r].lowercaseChar()) return false
        l++
        r--
    }
    return true
}
// Time: O(n)   Space: O(1)

fun removeDuplicates(nums: IntArray): Int {
    if (nums.isEmpty()) return 0
    var write = 1
    for (read in 1 until nums.size) {
        if (nums[read] != nums[read - 1]) {
            nums[write] = nums[read]
            write++
        }
    }
    return write
}
// Time: O(n)   Space: O(1)

fun moveZeroes(nums: IntArray) {
    var write = 0
    for (read in nums.indices) {
        if (nums[read] != 0) {
            val tmp = nums[write]
            nums[write] = nums[read]
            nums[read] = tmp
            write++
        }
    }
}
// Time: O(n)   Space: O(1)

fun threeSum(nums: IntArray): List<List<Int>> {
    nums.sort()
    val result = mutableListOf<List<Int>>()
    for (i in 0 until nums.size - 2) {
        if (i > 0 && nums[i] == nums[i - 1]) continue   // skip duplicates
        var l = i + 1
        var r = nums.size - 1
        while (l < r) {
            val sum = nums[i] + nums[l] + nums[r]
            when {
                sum == 0 -> {
                    result.add(listOf(nums[i], nums[l], nums[r]))
                    l++
                    r--
                    while (l < r && nums[l] == nums[l - 1]) l++
                    while (l < r && nums[r] == nums[r + 1]) r--
                }
                sum < 0 -> l++
                else -> r--
            }
        }
    }
    return result
}
// Time: O(n²)   Space: O(1) extra (ignoring output)

fun maxArea(height: IntArray): Int {
    var l = 0
    var r = height.size - 1
    var best = 0
    while (l < r) {
        val area = minOf(height[l], height[r]) * (r - l)
        best = maxOf(best, area)
        // Move the shorter wall; moving the taller one cannot help
        if (height[l] < height[r]) l++ else r--
    }
    return best
}
// Time: O(n)   Space: O(1)

fun merge(nums1: IntArray, m: Int, nums2: IntArray, n: Int) {
    var i = m - 1          // last real element in nums1
    var j = n - 1          // last element in nums2
    var k = m + n - 1      // last position in nums1
    while (j >= 0) {
        if (i >= 0 && nums1[i] > nums2[j]) {
            nums1[k--] = nums1[i--]
        } else {
            nums1[k--] = nums2[j--]
        }
    }
}
// Time: O(m + n)   Space: O(1)
// Trick: fill from the back so nothing is overwritten

fun longestPalindrome(s: String): String {
    var start = 0
    var maxLen = 0

    fun expand(left: Int, right: Int) {
        var l = left
        var r = right
        while (l >= 0 && r < s.length && s[l] == s[r]) {
            l--
            r++
        }
        val len = r - l - 1
        if (len > maxLen) {
            maxLen = len
            start = l + 1
        }
    }

    for (i in s.indices) {
        expand(i, i)       // odd length
        expand(i, i + 1)   // even length
    }
    return s.substring(start, start + maxLen)
}
// Time: O(n²)   Space: O(1)

fun sortColors(nums: IntArray) {
    var low = 0
    var mid = 0
    var high = nums.size - 1
    while (mid <= high) {
        when (nums[mid]) {
            0 -> { swap(nums, low, mid); low++; mid++ }
            1 -> mid++
            else -> { swap(nums, mid, high); high-- }   // do not move mid
        }
    }
}

fun swap(a: IntArray, i: Int, j: Int) {
    val t = a[i]; a[i] = a[j]; a[j] = t
}
// Time: O(n)   Space: O(1)

fun trap(height: IntArray): Int {
    var l = 0
    var r = height.size - 1
    var leftMax = 0
    var rightMax = 0
    var water = 0
    while (l < r) {
        if (height[l] < height[r]) {
            if (height[l] >= leftMax) leftMax = height[l]
            else water += leftMax - height[l]
            l++
        } else {
            if (height[r] >= rightMax) rightMax = height[r]
            else water += rightMax - height[r]
            r--
        }
    }
    return water
}
// Time: O(n)   Space: O(1)
